bool NormalValidationRun(){wchar_t expected[8]{};const DWORD count=GetEnvironmentVariableW(L"AEVRYND_EXPECT_GPU_VALIDATION_MODE",expected,DWORD(std::size(expected)));return count==6&&lstrcmpW(expected,L"normal")==0;}
