StaticMeshAssetDefinition3D Asset(std::string name,std::filesystem::path path,MaterialAlphaMode3D alphaMode=MaterialAlphaMode3D::Opaque,bool doubleSided=false){StaticMeshAssetDefinition3D value;value.name=std::move(name);value.meshPath=std::move(path);value.material=Material(alphaMode,doubleSided);value.generateLods=false;return value;}
bool BindSourceResourceContracts(StaticMeshAssetLibrary3D& library,std::span<HlodSourceBuildInput3D> sources,std::string_view sourceName="hlod-source"){const auto lease=library.ResolveRenderable(sourceName,1,true);if(!lease||!lease->Valid()||lease->Generation()>(std::numeric_limits<std::uint32_t>::max)())return false;const auto& renderable=lease->Renderable();const auto& mesh=renderable.lodLevelCount?renderable.lodLevels[0].mesh:renderable.nearMesh;const auto& material=renderable.lodLevelCount?renderable.lodLevels[0].material:renderable.nearMaterial;const auto shadow=HlodShadowSemanticFromRenderable3D(renderable);if(!shadow)return false;for(auto& source:sources){source.meshHandle=mesh.handle.value;source.materialHandle=material.textures.value;source.meshGeneration=static_cast<std::uint32_t>(lease->Generation());source.materialGeneration=source.meshGeneration;source.meshContentPrimary=mesh.handle.contentPrimary;source.meshContentSecondary=mesh.handle.contentSecondary;source.materialSemanticIdentity=material.textures.semanticIdentity;source.resourceOwnerIdentity=renderable.resourceOwnerIdentity;source.shadow=*shadow;}return true;}

class FakeReceiptSource final:public IGpuRetirementReceiptSource3D{
public:
 GpuRetirementReceipt3D CaptureGraphicsRetirementReceipt3D()override{return failCapture?GpuRetirementReceipt3D{}:MakeReceipt(17,next_++);}
 bool IsGraphicsRetirementComplete3D(GpuRetirementReceipt3D receipt)const override{return autoComplete||completed_.contains(receipt.FenceValue());}
 void CompleteAll(){for(std::uint64_t value=1;value<next_;++value)completed_.insert(value);}
 bool failCapture{},autoComplete{};
private:std::uint64_t next_{1};std::unordered_set<std::uint64_t> completed_{};
};

struct Fixture{std::shared_ptr<TerrainVegetationChunkPayload3D> payload{};std::string proxyName{};};
Fixture MakeFixture(StaticMeshAssetLibrary3D& library,TerrainVegetationChunkSettings3D settings,GlobalChunkCoordinate3D chunk,HlodClusterId3D clusterId,std::uint64_t generation,std::uint64_t serial,HlodCompatibility3D compatibility=HlodCompatibility3D::OpaqueCompatible,std::size_t reservedOverride=SIZE_MAX,std::string sourceName="hlod-source",float manifestOffset=0.f,MaterialAlphaMode3D alphaMode=MaterialAlphaMode3D::Opaque,bool doubleSided=false,bool overlap=false){
 auto proxy=library.PrepareHlodProxyCpu3D(settings.worldId,chunk,clusterId,generation,Asset({},"engine/assets/model-packs/poly-haven/rock_09/rock_09.aemesh",alphaMode,doubleSided));if(!proxy)return{};
 std::array<HlodSourceBuildInput3D,2> sources{{{{{serial,serial+1}},serial+10,1,1,1,1,{},{1,1,1},{-2,0,0},{},{1,1,1}},{{{serial,serial+2}},serial+11,1,1,1,1,{},{1,1,1},{2,0,0},{},{1,1,1}}}};
 if(overlap){sources[0].position={};sources[1].position={};}
 if(!BindSourceResourceContracts(library,sources,overlap?std::string_view{sourceName}:std::string_view{"hlod-source"}))return{};
 HlodClusterBuildInput3D cluster{};cluster.asset={clusterId,generation,{},5,1,.8f,1.2f,2,compatibility};cluster.resource={1,1,proxy->reservedPhysicalBytes,1,1,100,20};cluster.instance={clusterId,chunk,{},{1,1,1},{}};
 cluster.resource.proxyShadow=sources[0].shadow;cluster.sources=sources;const std::array clusters{cluster};auto data=BuildHlodData3D(clusters);if(!data)return{};
 const float firstX=overlap?0.f:-2.f+manifestOffset,secondX=overlap?0.f:2.f;std::array<TerrainVegetationHlodSource3D,2> manifestSources{{{sources[0].reference,sources[0].generation,sourceName,{chunk,{firstX,0,0}},{},{1,1,1}},{sources[1].reference,sources[1].generation,sourceName,{chunk,{secondX,0,0}},{},{1,1,1}}}};
 if(reservedOverride!=SIZE_MAX)proxy->reservedPhysicalBytes=reservedOverride;
 TerrainVegetationHlodCluster3D manifestCluster{};manifestCluster.id=clusterId;manifestCluster.generation=generation;manifestCluster.proxy=*proxy;manifestCluster.sources.assign(manifestSources.begin(),manifestSources.end());const std::array manifestClusters{manifestCluster};auto manifest=BuildTerrainVegetationHlodManifest3D(manifestClusters,*data);if(!manifest)return{};
 auto payload=std::make_shared<TerrainVegetationChunkPayload3D>();payload->globalChunk=chunk;HeightField3D field({{},5,5,2});field.Generate(static_cast<std::uint32_t>(serial),1,.05f,2);payload->heightField=field;payload->terrain=field.CreateMesh();payload->hlod=std::move(data);payload->hlodManifest=std::move(manifest);payload->cpuBytes=payload->terrain.vertices.size()*sizeof(Vertex3D)+payload->terrain.indices.size()*sizeof(std::uint32_t);return{std::move(payload),proxy->logicalName};
}
WorldChunkPayload3D Opaque(const Fixture& fixture){return fixture.payload?WorldChunkPayload3D{fixture.payload,fixture.payload->cpuBytes,fixture.payload->cpuBytes}:WorldChunkPayload3D{};}
